'use strict';
// Kadastro360 marka dosyalarını Render/GitHub dağıtımında otomatik oluşturur.
const fs = require('fs');
const path = require('path');
const ASSET_DATA = {"kadastro360-logo-horizontal.png":"","kadastro360-logo-vertical.png":"","kadastro360-mark.png":"","favicon.ico":"","favicon-32.png":"","favicon-16.png":"","apple-touch-icon.png":"","icon-192.png":"","icon-512.png":""};

function ensureBrandAssets() {
  const dir = path.join(__dirname, 'assets');
  fs.mkdirSync(dir, { recursive: true });
  const written = [];
  for (const [name, b64] of Object.entries(ASSET_DATA)) {
    const file = path.join(dir, name);
    const data = Buffer.from(b64, 'base64');
    let needsWrite = true;
    try {
      const current = fs.readFileSync(file);
      needsWrite = current.length !== data.length || !current.equals(data);
    } catch (_) {}
    if (needsWrite) {
      fs.writeFileSync(file, data);
      written.push(name);
    }
  }
  return { dir, written, count: Object.keys(ASSET_DATA).length };
}

if (require.main === module) {
  const result = ensureBrandAssets();
  console.log(`Kadastro360 marka dosyaları hazır: ${result.count}; yazılan: ${result.written.length}`);
}

module.exports = { ensureBrandAssets };
